/*--------------- Chữ ký số SignCA ---------------------*/

/* Modal ký số (USignAreaV2) */
.usign-ca-modal .modal-dialog {
    max-width: 90vw !important;
    width: 90vw !important;
    margin: 1.75rem auto;
}
.usign-ca-modal .modal-content {
    width: 100% !important;
    max-width: none !important;
}

/* Khối khu vực ký — SubjectMarkEdit & các trang khác */
.usign-area {
    clear: both;
    width: 100%;
    max-width: 1100px;
    margin: 28px auto 16px auto;
    padding: 0 12px;
    box-sizing: border-box;
    text-align: left;
}

.usign-area .usign-grid {
    display: flex;
    flex-wrap: wrap;
    margin: 0 -10px;
}

.usign-area .usign-col {
    flex: 1 1 280px;
    min-width: 260px;
    max-width: 100%;
    padding: 0 10px 16px 10px;
    box-sizing: border-box;
}

/* Thẻ chung */
.usign-area .usign-card {
    background: #fff;
    border: 1px solid #dce3ea;
    border-radius: 10px;
    box-shadow: 0 2px 8px rgba(30, 60, 90, 0.06);
    height: 100%;
    min-height: 200px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: box-shadow 0.2s ease, border-color 0.2s ease;
}
.usign-area .usign-card:hover {
    box-shadow: 0 4px 14px rgba(30, 60, 90, 0.1);
    border-color: #c5d4e0;
}

.usign-area .usign-card-head {
    padding: 12px 16px 10px 16px;
    border-bottom: 1px solid #eef2f6;
    background: linear-gradient(180deg, #f8fafb 0%, #fff 100%);
    font-size: 13px;
    line-height: 1.35;
    color: #1c9560;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.02em;
}
.usign-area .usign-card-head .usign-doc-label {
    color: #6b7c8f;
    font-weight: 600;
    font-size: 11px;
    display: block;
    margin-bottom: 2px;
    text-transform: none;
    letter-spacing: 0;
}

.usign-area .usign-card-body {
    padding: 14px 16px 16px 16px;
    flex: 1;
    display: flex;
    flex-direction: column;
}

/* Cột tập tin */
.usign-area .usign-card-file .usign-file-actions {
    margin-bottom: 12px;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}
.usign-area .uploader-wrap {
    overflow: hidden;
    position: relative;
    z-index: 2;
}
.usign-area .uploader-wrap:after {
    content: "";
    display: block;
    clear: both;
}
.usign-area .usign-uploader-slot {
    margin-top: 4px;
    padding-top: 10px;
    border-top: 1 dashed #e8edf2;
    font-size: 13px;
}
.usign-area .usign-uploader-slot .ajax-uploader-file-uploader {
    max-width: 100%;
}

/* Nút trong vùng SignCA */
.usign-area .btn-usign {
    background-color: #1c9560;
    border-color: #1c9560;
    color: #fff;
    font-weight: 600;
    padding: 6px 16px;
    border-radius: 6px;
    margin-top: auto;
    align-self: flex-start;
}
.usign-area .btn-usign:hover {
    background-color: #167a4e;
    border-color: #167a4e;
    color: #fff;
}
.usign-area .usign-file-actions .btn {
    border-radius: 6px;
    font-weight: 600;
    padding: 5px 14px;
    min-width: 72px;
}
.usign-area .usign-file-actions .btn-outline-success {
    color: #1c9560;
    border-color: #1c9560;
}
.usign-area .usign-file-actions .btn-outline-success:hover {
    background-color: #1c9560;
    border-color: #1c9560;
    color: #fff;
}
.usign-area .usign-file-actions .btn-outline-secondary {
    color: #5a6a7a;
    border-color: #c5ced8;
}
.usign-area .usign-file-actions .btn-outline-secondary:hover {
    background-color: #5a6a7a;
    border-color: #5a6a7a;
    color: #fff;
}

.usign-area .text-usign {
    color: #1c9560 !important;
}

/* Meta: người ký, thời gian */
.sign-area .usign-meta {
    margin-bottom: 10px;
}
.sign-area .usign-meta-item {
    display: flex;
    align-items: flex-start;
    margin-bottom: 8px;
    font-size: 13px;
    color: #4a5568;
    line-height: 1.4;
}
.sign-area .usign-meta-item .fa {
    width: 18px;
    margin-right: 8px;
    margin-top: 2px;
    color: #1c9560;
    text-align: center;
    flex-shrink: 0;
}
.sign-area .user {
    padding: 0;
    color: #2d3748;
    font-weight: 500;
    word-break: break-word;
}
.sign-area .time {
    font-size: 12px;
    color: #718096;
    display: none;
}

.sign-area .usign-status-wrap {
    margin-top: 4px;
    margin-bottom: 10px;
}
.sign-area .status {
    display: inline-block;
    font-weight: 700;
    font-size: 13px;
    padding: 6px 12px 6px 12px;
    border-radius: 20px;
    color: #4a5568;
    background: #f1f3f5;
    border: 1px solid #e2e8f0;
}

/* Viền trái theo trạng thái */
.usign-area .sign-area-0 {
    border-left: 4px solid #94a3b8;
}
.usign-area .sign-area-1 {
    border-left: 4px solid #f0b429;
}
.usign-area .sign-area-2 {
    border-left: 4px solid #1c9560;
}
.usign-area .sign-area-3,
.usign-area .sign-area-4 {
    border-left: 4px solid #e53e3e;
}

/* Chưa ký */
.sign-area-0 .status {
    color: #64748b;
    background: #f8fafc;
    border-color: #cbd5e1;
}

/* Đang chờ xác thực */
.sign-area-1 .status {
    padding-left: 32px;
    font-style: italic;
    color: #b7791f;
    background: #fffbeb;
    border-color: #fcd34d;
    background-image: url("Images/Site/loader.gif");
    background-repeat: no-repeat;
    background-position: 10px center;
    background-size: 18px 18px;
}

/* Đã ký */
.sign-area-2 .user {
    color: #0d7a50;
}
.sign-area-2 .time {
    color: #2f855a;
    display: block;
}
.sign-area-2 .status {
    padding-left: 32px;
    font-style: normal;
    color: #0d7a50;
    background: #ecfdf5;
    border-color: #6ee7b7;
    background-image: url("Images/Site/verified.png");
    background-repeat: no-repeat;
    background-position: 10px center;
    background-size: 18px 18px;
}

/* Lỗi / từ chối */
.sign-area-3 .status,
.sign-area-4 .status {
    color: #c53030;
    background: #fff5f5;
    border-color: #feb2b2;
}

.usign-area #lblMsg,
.usign-area .usign-msg {
    display: block;
    width: 100%;
    padding: 8px 10px 0 10px;
    font-size: 13px;
    color: #c53030;
}

/* Bootstrap row fallback — giữ col-md-4 nếu flex không áp dụng */
.usign-area .row.g-3 {
    --bs-gutter-x: 1rem;
    --bs-gutter-y: 1rem;
}
.usign-area .row.g-3 > [class*="col-"] > .usign-card,
.usign-area .row.g-3 > [class*="col-"] > .border.rounded,
.usign-area .row.g-3 > [class*="col-"] > .uploader-wrap {
    height: 100%;
}

.usign-area .row.g-3 > [class*="col-"] > .border.rounded.p-3,
.usign-area .row.g-3 > [class*="col-"] > .uploader-wrap.border {
    border: none !important;
    background: transparent !important;
    padding: 0 !important;
}

@media (max-width: 767px) {
    .usign-area {
        padding: 0 8px;
    }
    .usign-area .usign-col {
        flex: 1 1 100%;
    }
}

